"""Abdominal wall, pelvis / anorectum, spine fascia, hand and finger rows."""
from rows_common import P, S

# =================================================================== RECTUS ABDOMINIS (+ sheath) - owner example (incl. the 'rectum/rectus' ambiguity)
S("rectus_abdominis.intersections", "rectus_abdominis", "muscle_tendon_junction", "Rectus abdominis: number of tendinous intersections (per side)", [
    (3, "broyles2018", "30 of 32 cadavers had 3 paired intersections, 2 had 4 (55 hemi-abdomens, 168 intersections)"),
    (3, "anita2015", "3 in 96.29 % of 54 cadavers; 4 in one; 5 in one"),
    (4, "broyles2018", "2 of 32 cadavers"), (5, "anita2015", "1 of 54 cadavers")],
  note="Usual count 3 per side (=> 4 muscle bellies); 4-5 are variants.")
P("rectus_abdominis", "intersection_proximal", "muscle_tendon_junction", "Tendinous intersection 1 (most proximal)", "Transverse fibrous band; adherent to the anterior rectus sheath.", ["broyles2018", "anita2015"], ev="cadaver n=55 hemi-abdomens; n=54", var="3 usual", setid="rectus_abdominis.intersections",
  note="Position along the muscle: textbook levels (xiphoid, umbilicus, between) are NOT in the cited abstracts -> no geometry.")
P("rectus_abdominis", "intersection_middle", "muscle_tendon_junction", "Tendinous intersection 2", "As intersection 1.", ["broyles2018", "anita2015"], ev="cadaver", setid="rectus_abdominis.intersections")
P("rectus_abdominis", "intersection_distal", "muscle_tendon_junction", "Tendinous intersection 3 (most distal; marks the arcuate line)", "The arcuate line lies at the most distal intersection (80 subjects; arcuate line present in 80.4 %, 93 % of men; more than a third of women lacked it).", ["mwachaka2010", "broyles2018"], ev="autopsy/dissection n=80; n=55",
  setid="rectus_abdominis.intersections", related=["rectus_sheath"])
P("rectus_abdominis", "intersection_accessory_fourth", "muscle_tendon_junction", "Accessory (4th) tendinous intersection", "Present in 2 of 32 cadavers (Broyles) and 1 of 54 (Anita); a 5th in 1 of 54.", ["broyles2018", "anita2015"], ev="cadaver", var="~3-6 %", setid="rectus_abdominis.intersections")
P("rectus_abdominis", "intersection_full_thickness_variant", "muscle_tendon_junction", "Full-thickness intersections (anterior to posterior rectus sheath)", "Most intersections are incomplete (anterior sheath only); 18 % of 168 were full thickness with no intervening muscle or neurovascular structure; 42 % of hemi-abdomens had at least one.", ["broyles2018"], ev="cadaver n=55 hemi-abdomens", var="18 % of intersections")
P("rectus_sheath", "anterior_layer", "ligament_component", "Anterior rectus sheath (ventral lamina)", "Essentially oblique collagen fibril bundles that intermingle; firmly adherent to the tendinous intersections.", ["axer2001", "broyles2018"], cls="fascia", ev="confocal microscopy n=12; cadaver n=55")
P("rectus_sheath", "posterior_layer", "ligament_component", "Posterior rectus sheath (dorsal lamina)", "Chiefly transverse fibril bundles; ends at the arcuate line (absent below it).", ["axer2001", "mwachaka2010"], cls="fascia", ev="confocal microscopy n=12; n=80")
P("rectus_sheath", "arcuate_line", "ligament_component", "Arcuate line (of Douglas): lower edge of the posterior sheath", "Present in 80.4 % of 80 subjects, as a single bilateral arcade at the most distal intersection, in the upper half of the umbilicus-to-pubic-symphysis line in most; absent in more than a third of women.", ["mwachaka2010"], cls="fascia", ev="autopsy/dissection n=80", var="80.4 %")
P("linea_alba", "supraumbilical_part", "ligament_component", "Linea alba: supra-umbilical part", "Three laminae from ventral to dorsal: lamina fibrae obliquae, lamina fibrae transversae, small inconstant lamina fibrae irregularium. Diastasis threshold above the umbilicus: 10 mm (<45 y) / 15 mm (>45 y).", ["axer2001", "rath1996"], cls="fascia", ev="confocal microscopy n=12 (14 segments); n=40", setid="linea_alba.regions")
P("linea_alba", "umbilical_part", "ligament_component", "Linea alba: umbilical part", "Diastasis recti is defined by an inter-rectus separation above 27 mm at the umbilical ring (both age groups; Rath 1996).", ["axer2001", "rath1996"], cls="fascia", ev="n=12; n=40", setid="linea_alba.regions")
P("linea_alba", "transition_zone", "ligament_component", "Linea alba: transition zone", "Region between umbilical and infra-arcuate parts.", ["axer2001"], cls="fascia", ev="confocal microscopy n=12", setid="linea_alba.regions")
P("linea_alba", "infraarcuate_part", "ligament_component", "Linea alba: infra-arcuate part", "Below the arcuate line (no posterior sheath). Diastasis threshold below the umbilicus: 9 mm (<45 y) / 14 mm (>45 y).", ["axer2001", "rath1996"], cls="fascia", ev="n=12; n=40", setid="linea_alba.regions")
S("linea_alba.regions", "linea_alba", "ligament_component", "Linea alba: craniocaudal regions", [(4, "axer2001", "supraumbilical, umbilical, transition zone, infra-arcuate")])

# =================================================================== PELVIC FLOOR / ANORECTUM (owner example, 'rectum')
S("levator_ani.parts", "levator_ani", "head_belly", "Levator ani: number of parts", [
    (5, "kearney2004", "5 origin-insertion pairs: puboperineal, pubovaginal, puboanal, puborectal, iliococcygeal (16 terms in use)"),
    (3, "stoker2009", "traditional division puborectalis / pubococcygeus / iliococcygeus (as in this project's muscle record)")])
for slug, nm, ds in [("puboperineal", "Puboperineal part", "Pubic origin to the perineal body."), ("pubovaginal", "Pubovaginal part (female)", "Pubic origin to the vaginal wall."),
                     ("puboanal", "Puboanal part", "Pubic origin to the anus / intersphincteric groove. Z-Anatomy carries the 'pubo-analis muscle' as a separate mesh."),
                     ("puborectal", "Puborectal part (puborectalis)", "Forms the sling behind the anorectal junction; the upper outer half of the sphincter in Stoker's account."), ("iliococcygeal", "Iliococcygeal part", "From the tendinous arch to the anococcygeal raphe / coccyx.")]:
    P("levator_ani", slug, "head_belly", nm, ds + " Part names from Kearney 2004; the descriptions beyond the part name are not all in the abstract.", ["kearney2004"] + (["stoker2009"] if slug == "puborectal" else []), ev="literature review (265 studies, 9 qualifying) of origin-insertion pairs",
      setid="levator_ani.parts", z=(["zan_pubo_analis_muscle_{s}"] if slug == "puboanal" else []), geom=(dict(rule="z_part_mesh") if slug == "puboanal" else None))
P("external_anal_sphincter", "classic_tripartite_subdivision", "head_belly", "Classic subcutaneous / superficial / deep subdivision (NOT confirmed)", "Histology-guided dissection (fetal, newborn, adult pelves) did not confirm the classical tripartite subdivision; the external sphincter turns into the internal sphincter and encloses the longitudinal muscle bundles; it is not a complete circle in some planes.",
  ["fritsch2002"], ev="serial sections + MRI correlation", var="subdivision disputed", setid="external_anal_sphincter.parts")
P("external_anal_sphincter", "outer_sphincter_vs_puborectalis", "head_belly", "Outer striated layer: external sphincter (lower outer half) + puborectalis (upper outer half)", "The anal sphincter is multilayered: smooth-muscle internal sphincter inside, outer striated layer made of the external sphincter below and puborectalis above; the external sphincter is continuous with the rectum at the anorectal junction.",
  ["stoker2009"], ev="review", setid="external_anal_sphincter.parts")
S("external_anal_sphincter.parts", "external_anal_sphincter", "head_belly", "External anal sphincter: parts", [(3, "fritsch2002", "classical three-part subdivision (not confirmed)"), (1, "fritsch2002", "single complex with the longitudinal muscle layer")])
P("rectum", "lateral_ligament_medial_part", "fascial_passage", "Lateral ligament of the rectum: medial part (rectal branches of the pelvic plexus)", "Lateral ligament divides into a lateral and a medial part by its relation to the pelvic plexus; the medial part consists of rectal branches of the pelvic plexus with connective tissue.", ["sato1991"], ev="dissection n=83 pelvic halves",
  passes=dict(kind="nerve", traversing=[], traversing_text="rectal branches of the pelvic (inferior hypogastric) plexus", through="lateral ligament of the rectum (endopelvic fascia)"), related=["inferior_hypogastric_plexus"])
P("rectum", "lateral_ligament_lateral_part", "fascial_passage", "Lateral ligament of the rectum: lateral part (superoanterior = middle rectal artery; inferoposterior = pelvic splanchnic nerves)", "The middle rectal artery was present in the lateral ligament in only 22.2 % (18/81); the inferoposterior subdivision contains the pelvic splanchnic nerves. Church 1987: the middle rectal artery runs below the lateral ligaments on levator ani; accessory middle rectal artery in 25 %.", ["sato1991", "church1987"], ev="dissection n=83; review",
  var="MRA in ligament 22.2 % (Sato) vs not in ligament (Church)", passes=dict(kind="vessel+nerve", traversing=["middle_rectal_a"], traversing_text="middle rectal artery (variable), pelvic splanchnic nerves", through="lateral ligament of the rectum"), related=["middle_rectal_a"],
  note="Two sources disagree on whether the middle rectal artery is inside the ligament: recorded as a conflict, not resolved.")
P("rectum", "denonvilliers_fascia_penetration", "fascial_passage", "Penetration of Denonvilliers' fascia by the middle rectal artery", "According to Church 1987 the middle rectal artery reaches the rectum by penetrating Denonvilliers' fascia.", ["church1987"], ev="review", passes=dict(kind="vessel", traversing=["middle_rectal_a"], through="Denonvilliers' fascia (rectovesical/rectovaginal septum)"), related=["middle_rectal_a"])
P("rectum", "rectosacral_fascia_waldeyer", "fascial_passage", "Rectosacral fascia (Waldeyer): posterior attachment of the rectum to S3-S4", "Dense connective tissue between the posterior wall of the rectum and the 3rd-4th sacral vertebrae, carrying branches of the lateral and median sacral vessels and sacral splanchnic nerves; must be incised deliberately to enter the presacral space.", ["sato1991", "church1987"], ev="dissection n=83; review",
  passes=dict(kind="vessel+nerve", traversing=[], traversing_text="branches of lateral and median sacral vessels; sacral splanchnic nerves", through="rectosacral fascia"))
P("rectum", "anorectal_junction_puborectalis_sling", "fascial_passage", "Anorectal junction through the puborectalis sling", "Puborectalis forms the upper outer half of the striated outer sphincter layer at the anorectal junction (the project muscle record describes the U-shaped sling behind the junction); the external sphincter is continuous with the rectum there.", ["stoker2009", "kearney2004"], ev="review",
  passes=dict(kind="organ", traversing=["rectum"], through="levator hiatus / puborectalis sling"), related=["levator_ani", "external_anal_sphincter"],
  note="Ambiguity: the owner's word 'ברקטום' could mean rectum or rectus; both are covered (rectum here, rectus abdominis + rectus sheath above).")
P("pudendal_n", "pudendal_canal_alcock", "fascial_passage", "Pudendal canal (Alcock): pudendal nerve and vessels in a split of the obturator fascia", "Canal wall is formed by splitting of the obturator fascia (and not of the lunate fascia); mean length 1.6 cm in adults; contains the pudendal nerve and vessels; branches arise inside it in nearly all.", ["shafik1999", "robert1998"], ev="cadaver n=26 (16 adults)",
  cls="nerve", passes=dict(kind="nerve+vessel", traversing=["pudendal_n", "internal_pudendal_a"], through="obturator fascia (pudendal canal)"), related=["internal_pudendal_a"])
P("pudendal_n", "pudendal_nerve_conflict_sites", "fascial_passage", "Pudendal nerve conflict sites: sacrotuberous-sacrospinous gap, Alcock canal, falciform process", "Three possible conflictual settings for the pudendal nerve and its branches.", ["robert1998"], ev="cadaver + clinical series 170 operated patients",
  cls="nerve", passes=dict(kind="nerve", traversing=["pudendal_n"], through="between sacrotuberous and sacrospinous ligaments; pudendal canal; falciform process of sacrotuberous ligament"), related=["sacrotuberous_ligament", "sacrospinous_ligament"])

# =================================================================== THORACOLUMBAR FASCIA / BACK
P("posterior_layer_tlf", "superficial_lamina", "ligament_component", "Posterior layer: superficial lamina", "Dominated by the aponeuroses of latissimus dorsi and serratus posterior inferior.", ["willard2012"], cls="fascia", ev="review")
P("posterior_layer_tlf", "deep_lamina_paraspinal_retinacular_sheath", "ligament_component", "Posterior layer: deep lamina (paraspinal retinacular sheath)", "Encapsulates the paraspinal muscles; forms the lumbar interfascial triangle (LIFT) with the middle layer.", ["willard2012"], cls="fascia", ev="review")
P("middle_layer_tlf", "lateral_raphe", "ligament_component", "Lateral raphe (junction with transversus abdominis aponeurosis)", "Thickened dense connective tissue marking the junction of the hypaxial (abdominal) and epaxial (paraspinal) compartments.", ["willard2012"], cls="fascia", ev="review")
P("posterior_layer_tlf", "thoracolumbar_composite_sacral", "ligament_component", "Thoracolumbar composite at the lumbosacral base", "All layers fuse into a composite that attaches to the PSIS and the sacrotuberous ligament.", ["willard2012"], cls="fascia", ev="review", related=["sacrotuberous_ligament"])
P("posterior_layer_tlf", "superior_cluneal_nerve_crossing", "fascial_passage", "Superior cluneal nerves crossing the posterior iliac crest", "Three branches (medial, intermediate, lateral) cross the iliac crest a mean 5.0, 6.5 and 7.3 cm lateral to the PSIS; middle cluneal nerves originate about at the PSIS level (2 cm above to 1.5 cm below) and traverse the paraspinal muscles to the dorsal sacrum.", ["tubbs2010", "willard2012"], cls="fascia", ev="cadaver n=20 sides",
  passes=dict(kind="nerve", traversing=["cluneal_nn_superior", "cluneal_nn_middle"], through="thoracolumbar fascia / gluteal fascia at the iliac crest"), related=["cluneal_nn_superior", "cluneal_nn_middle"], var="intermediate branch absent 4/20, lateral 5/20")
